-- Generated by scripts/build-deals-seed.py from supabase/seed/deals.csv.
-- Re-running updates names, categories, and blurbs in place by url.

on conflict (url) do update set
  name = excluded.name, domain = excluded.domain, category = excluded.category,
  blurb = excluded.blurb, sort = excluded.sort, offer = excluded.offer,
  value = excluded.value, value_amount = excluded.value_amount;
